-- insert-malaga-centers.sql
-- Inserta los 152 centros de educacion infantil de primer ciclo (0-3 anos)
-- del termino municipal de Malaga capital investigados y humanizados en este sprint.
-- Fuente primaria: "Centros de primer ciclo de educacion infantil en Andalucia, con
-- alumnado matriculado" (Junta de Andalucia, Consejeria de Desarrollo Educativo y
-- Formacion Profesional, portal de datos abiertos), filtrado por D_MUNICIPIO='Málaga'.
-- Complementado con webs oficiales propias de un subconjunto de centros privados (varias
-- cadenas con multiples sedes) y de la Universidad de Malaga (Francisca Luque, titularidad
-- publica) para confirmar servicios concretos. Ver docs/data-sources-malaga.md y
-- data/enrichment/malaga-centers.json.
--
-- Ambito: unicamente el termino municipal de Malaga capital (D_MUNICIPIO='Málaga' en la
-- fuente oficial). Se excluyen explicitamente los otros 66 municipios de la provincia de
-- Malaga (Torremolinos, Benalmadena, Alhaurin de la Torre, Rincon de la Victoria, Marbella,
-- Mijas, Fuengirola, Velez-Malaga, etc.) aunque aparecieran en la misma fuente provincial.
--
-- Ownership: solo se ha usado 'publico' para los 5 centros de la red genuina de titularidad
-- de la Junta de Andalucia (La Palma, Los Asperones, Reyes Magos, San Jose, Santo Angel) y
-- para la escuela infantil de la Universidad de Malaga (Francisca Luque, titularidad publica
-- universitaria). Los centros privados adheridos al Programa de Ayuda a las Familias de la
-- Junta de Andalucia (incluidas cadenas que la propia fuente oficial etiqueta D_TIPO=Publico
-- por gestion indirecta/adhesion, como Novaschool y 5 Chupetes) llevan ownership='privado',
-- nunca 'concertado': Andalucia no tiene concierto educativo formal para el primer ciclo de
-- infantil (0-3 anos), siguiendo el mismo criterio validado tras la correccion post-auditoria
-- de Sevilla (2026-07-12). Ver docs/malaga-quality-report.md, seccion 1.
--
-- Todos los centros entran con status='draft' (no visibles publicamente por RLS hasta
-- cambiarlos a 'published' manualmente tras auditoria, igual que en Madrid, Barcelona,
-- Valencia, Zaragoza, Murcia, Sevilla y Palma).
-- No toca ningun centro de Madrid, Barcelona, Valencia, Zaragoza, Murcia, Sevilla ni Palma.
-- No borra ni modifica filas existentes (upsert por slug: si un slug ya existe se actualiza,
-- no se duplica).
-- Generado: 2026-07-12. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

-- Aseguramos que la ciudad "malaga" existe antes de insertar sus centros.
INSERT INTO cities (slug, name, province, region)
VALUES ('malaga', 'Málaga', 'Málaga', 'Andalucía')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO centers (
  slug, name, type, ownership, street, postal_code, city_slug, city_name, neighborhood, district, neighborhood_barrio, latitude, longitude, phone, email, website, age_min_months, age_max_months, schedule, services, short_description, long_description, images, faqs, is_claimed, is_verified, social_links, pedagogical_approach, source_url, source_urls_secondary, verified_at, verification_status, confidence_level, data_conflicts, status
)
VALUES
